impl markup::Transform for super::Alignment {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.spreadsheet(), super::Context::alignment, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        Self {
            horizontal: self.horizontal.clone(),
            indent: self.indent.clone(),
            justify_last_line: self.justify_last_line.clone(),
            reading_order: self.reading_order.clone(),
            relative_indent: self.relative_indent.clone(),
            shrink_to_fit: self.shrink_to_fit.clone(),
            text_rotation: self.text_rotation.clone(),
            unknown: markup::transform_unknown(&self.unknown, ctx, &markup::Rebase::default()),
            vertical: self.vertical.clone(),
            wrap_text: self.wrap_text.clone(),
        }
    }
}

impl markup::Visit for super::Alignment {
    fn visit(&self, visitor: &mut dyn markup::Visitor) {
        let next = markup::show(visitor.spreadsheet(), super::Visitor::alignment, self);
        if next == markup::Descend::Yes {
            self.visit_children(visitor);
        }
    }

    fn visit_children(&self, visitor: &mut dyn markup::Visitor) {
        markup::Walk::new(&self.unknown).finish(visitor);
    }
}

