impl markup::Item for super::FillContent {
    fn is_declared(&self) -> bool {
        !matches!(self, Self::Other(_))
    }
}

impl markup::Transform for super::FillContent {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.spreadsheet(), super::Context::fill_content, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        match self {
            Self::Gradient(arm) => Self::Gradient(arm.transform(ctx)),
            Self::Other(node) => Self::Other(node.transform(ctx)),
            Self::Pattern(arm) => Self::Pattern(arm.transform(ctx)),
        }
    }
}

